helpers:
function JQ(S: WideString): String;
var K,V: Integer;
begin
  Result := '"';
  for K := 1 to Length(S) do begin
    V := Ord(S[K]);
    if (V < 32) or (V > 126) or (V = 34) or (V = 92) then
      Result := Result + '\u' + IntToHex(V,4)
    else Result := Result + S[K];
  end;
  Result := Result + '"';
end;
